/* One frame in both directions. `encoded` carries the 0xAA marker the
 * ESP32 receives; `encoded_tx` the 0xCC poll response it emits and the
 * STM32 receives. Same length, same body -- only the marker and the
 * checksum over it differ. Both are built here so that the bytes one
 * end produces are literally the bytes the other end is asserted
 * against, with no fixup written in either test file. */
typedef struct {
    const char    *name;
    uint32_t       can_id;
    uint8_t        dlc;
    uint8_t        extended;
    uint8_t        remote;
    const uint8_t *data;
    const uint8_t *encoded;      /* 0xAA: STM32 -> ESP32 */
    size_t         encoded_len;
    const uint8_t *encoded_tx;   /* 0xCC: ESP32 -> STM32 */
} ramn_vector_t;

/* Malformed frames, in both directions: `encoded` carries the 0xAA
 * marker the ESP32 receives, `encoded_tx` the 0xCC the STM32 does.
 * Rewriting a marker at test time means recomputing the checksum,
 * which repairs the defect `bad checksum` exists to test. */
typedef struct {
    const char    *name;
    const uint8_t *encoded;      /* 0xAA: STM32 -> ESP32 */
    size_t         encoded_len;
    const uint8_t *encoded_tx;   /* 0xCC: ESP32 -> STM32 */
    size_t         encoded_tx_len;
} ramn_reject_vector_t;

