/* CAN identifiers whose high byte matches a v1 type code.
 * Every one must decode as an ordinary CAN frame. */
/* Both directions: `encoded` carries the 0xCC marker the STM32
 * receives, `encoded_rx` the 0xAA marker the ESP32 receives. Each end
 * decodes one of them and refuses the other, so a family emitted in
 * one direction only is usable by one end only. */
typedef struct {
    const char    *name;
    uint32_t       can_id;
    const uint8_t *encoded;      /* 0xCC: ESP32 -> STM32 */
    size_t         encoded_len;
    const uint8_t *encoded_rx;   /* 0xAA: STM32 -> ESP32 */
    size_t         encoded_rx_len;
} ramn_adversarial_vector_t;

